const settings = $('설정').first().json;
const rows = $input.all().map((item) => item.json);
const failed = rows.some((row) => row.error != null);

function parsePolygon(wkt) {
  const match = String(wkt ?? '').trim().match(/^POLYGON\s*\(\((.*)\)\)$/i);
  if (!match) return null;
  const ringText = match[1].split(/\)\s*,\s*\(/)[0];
  const ring = ringText.split(',').map((pair) => {
    const values = pair.trim().split(/\s+/).map(Number);
    return values.length >= 2 && values.every(Number.isFinite)
      ? { lat: values[0], lng: values[1] }
      : null;
  });
  return ring.length >= 4 && ring.every(Boolean) ? ring : null;
}

const areas = failed ? [] : rows
  .filter((row) => row.AREA_ID != null && row.AREA_NAME != null && row.BOUNDARY_WKT != null)
  .map((row) => ({
    areaId: Number(row.AREA_ID),
    areaName: String(row.AREA_NAME),
    ring: parsePolygon(row.BOUNDARY_WKT),
  }))
  .filter((area) => Number.isSafeInteger(area.areaId) && area.ring);

const hasDaechi = areas.some((area) => area.areaName === '대치동');
let reason = null;
if (failed) reason = 'DB_AREA_FAILED';
else if (areas.length === 0) reason = 'AREA_NOT_FOUND';
else if (hasDaechi && !settings.hasTopisKey) reason = 'TOPIS_API_KEY_MISSING';

return [{
  json: {
    ...settings,
    ok: reason === null,
    stage: reason === 'TOPIS_API_KEY_MISSING' ? 'KEY_CHECK' : 'AREA',
    reason,
    areas,
    hasDaechi,
  },
}];

const context = $('학원가 경계 준비').first().json;
const response = $input.first().json;
const status = Number(response.statusCode);

function parseBody(value) {
  if (value && typeof value === 'object') return value;
  try { return JSON.parse(String(value ?? '')); } catch { return null; }
}
function failureReason(stage, httpStatus, code) {
  if (httpStatus !== 200) return Number.isInteger(httpStatus) ? 'HTTP_' + httpStatus : 'HTTP_ERROR';
  const text = String(code ?? '');
  return /^[A-Z0-9_-]{1,50}$/.test(text) ? text : text ? 'RESULT_CODE_INVALID' : 'RESULT_CODE_MISSING';
}
function asArray(value) {
  if (Array.isArray(value)) return value;
  return value && typeof value === 'object' ? [value] : [];
}

// 전국 행을 끝까지 들고 가지 않도록 페이지마다 공영이면서 학원가 경계 사각형 ±0.02°(약 2km) 안인 행만 남긴다. 1km 판정은 '표준데이터 범위 필터'가 한다
function keepNear(rows, areas) {
  const pad = 0.02;
  const boxes = areas.map((area) => {
    const lats = area.ring.map((point) => point.lat);
    const lngs = area.ring.map((point) => point.lng);
    return { minLat: Math.min(...lats) - pad, maxLat: Math.max(...lats) + pad, minLng: Math.min(...lngs) - pad, maxLng: Math.max(...lngs) + pad };
  });
  return rows.filter((row) => {
    if (String(row.prkplceSe ?? '').trim() !== '공영') return false;
    const lat = Number(row.latitude);
    const lng = Number(row.longitude);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return false;
    return boxes.some((box) => lat >= box.minLat && lat <= box.maxLat && lng >= box.minLng && lng <= box.maxLng);
  });
}

