const code = parsed?.header?.resultCode;
const total = Number(parsed?.body?.totalCount);
const validTotal = Number.isSafeInteger(total) && total >= 0;
const ok = status === 200 && code === '00' && validTotal;
const rawItems = ok ? asArray(parsed?.body?.items?.item) : [];
const items = keepNear(rawItems, context.areas);
const pageCount = validTotal ? Math.ceil(total / context.pageSize) : 0;
