const context = $input.first().json;
const metersPerLat = 110540;

function pointInPolygon(point, ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i, i += 1) {
    const xi = ring[i].lng;
    const yi = ring[i].lat;
    const xj = ring[j].lng;
    const yj = ring[j].lat;
    const crosses = ((yi > point.lat) !== (yj > point.lat))
      && point.lng < ((xj - xi) * (point.lat - yi)) / (yj - yi) + xi;
    if (crosses) inside = !inside;
  }
  return inside;
}

function segmentDistanceM(point, first, second) {
  const lngScale = 111320 * Math.cos(point.lat * Math.PI / 180);
  const ax = (first.lng - point.lng) * lngScale;
  const ay = (first.lat - point.lat) * metersPerLat;
  const bx = (second.lng - point.lng) * lngScale;
  const by = (second.lat - point.lat) * metersPerLat;
  const dx = bx - ax;
  const dy = by - ay;
  const lengthSquared = dx * dx + dy * dy;
  const t = lengthSquared === 0 ? 0 : Math.max(0, Math.min(1, -(ax * dx + ay * dy) / lengthSquared));
  return Math.hypot(ax + t * dx, ay + t * dy);
}

function polygonDistanceM(point, ring) {
  if (pointInPolygon(point, ring)) return 0;
  let minimum = Infinity;
  for (let i = 0; i < ring.length; i += 1) {
    minimum = Math.min(minimum, segmentDistanceM(point, ring[i], ring[(i + 1) % ring.length]));
  }
  return minimum;
}

