      selectedDistance = distance;
    }
  }
  if (!selectedArea || selectedDistance > 1000) continue;
  lots.push({ ...row, areaId: selectedArea.areaId, areaName: selectedArea.areaName, areaDistanceM: Math.round(selectedDistance) });
