const context = $input.first().json;

function text(value) {
  return String(value ?? '').trim();
}
function normalizeName(value) {
  return text(value)
    .replace(/\s+/g, '')
    .replace(/공영주차장/g, '')
    .replace(/주차장/g, '')
    .replace(/\(구\)|\(시\)/g, '')
    .replace(/공영/g, '');
}
function dongs(value) {
  return [...text(value).matchAll(/[가-힣0-9]+동/g)].map((match) => match[0]);
}
function numberOrNull(value) {
  if (value === null || value === undefined || text(value) === '') return null;
  const number = Number(value);
  return Number.isFinite(number) ? Math.round(number) : null;
}
// 0원 1일권·0원 1일 최대 요금은 '없음'으로 본다(표준데이터에 dayCmmtkt "0"이 있다)
function positiveOrNull(value) {
  const number = nonNegativeOrNull(value);
  return number === null || number === 0 ? null : number;
}

function nonNegativeOrNull(value) {
  const number = numberOrNull(value);
  return number !== null && number >= 0 ? number : null;
}
function toTime(value) {
  const match = text(value).match(/^(\d{2}):?(\d{2})$/);
  if (!match) return null;
  const hour = Number(match[1]);
  const minute = Number(match[2]);
  if ((hour === 24 && minute === 0) || (hour === 23 && minute === 59)) return '23:59:59';
  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) return null;
  return match[1] + ':' + match[2] + ':00';
}
function timePair(openValue, closeValue) {
  if (!text(openValue) || !text(closeValue)) return [null, null];
  const open = toTime(openValue);
  const close = toTime(closeValue);
  return open && close ? [open, close] : [null, null];
}
function addPair(unitValue, feeValue) {
  const unit = nonNegativeOrNull(unitValue);
  const fee = nonNegativeOrNull(feeValue);
  return unit !== null && unit > 0 && fee !== null && fee > 0 ? [unit, fee] : [null, null];
}
function validDate(value) {
  const date = text(value).slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(date) ? date : null;
}
function standardValues(row) {
  const free = text(row.parkingchrgeInfo) === '무료';
  const weekday = timePair(row.weekdayOperOpenHhmm, row.weekdayOperColseHhmm);
  const saturday = timePair(row.satOperOperOpenHhmm, row.satOperCloseHhmm);
  const holiday = timePair(row.holidayOperOpenHhmm, row.holidayCloseOpenHhmm);
  const additional = addPair(row.addUnitTime, row.addUnitCharge);
  return {
    weekdayOpen: weekday[0],
    weekdayClose: weekday[1],
    satOpen: saturday[0],
    satClose: saturday[1],
    holidayOpen: holiday[0],
    holidayClose: holiday[1],
    baseMin: free && !text(row.basicTime) ? 0 : (nonNegativeOrNull(row.basicTime) ?? 0),
    baseFee: free ? 0 : (nonNegativeOrNull(row.basicCharge) ?? 0),
    addUnitMin: additional[0],
    addFee: additional[1],
  };
}
function seoulValues(row) {
  const weekday = timePair(row.WD_OPER_BGNG_TM, row.WD_OPER_END_TM);
  const saturday = timePair(row.WE_OPER_BGNG_TM, row.WE_OPER_END_TM);
  const holiday = timePair(row.LHLDY_BGNG, row.LHLDY);
  const additional = addPair(row.ADD_UNIT_TM_MNT, row.ADD_CRG);
  return {
    weekdayOpen: weekday[0],
    weekdayClose: weekday[1],
    satOpen: saturday[0],
    satClose: saturday[1],
    holidayOpen: holiday[0],
    holidayClose: holiday[1],
    baseMin: nonNegativeOrNull(row.PRK_HM) ?? 0,
    baseFee: nonNegativeOrNull(row.PRK_CRG) ?? 0,
    addUnitMin: additional[0],
    addFee: additional[1],
  };
}
// 서울시 값이 틀린 요금(빈 요금 → 0원)이나 빈 운영 시간을 만들면 쓰지 않는다. CHGD_FREE_SE 'Y'가 유료다
function seoulUsable(row, values) {
  if (values.weekdayOpen === null || values.weekdayClose === null) return false;
  const paid = text(row.CHGD_FREE_SE) !== 'N' && text(row.CHGD_FREE_NM) !== '무료';
  return !paid || (values.baseFee > 0 && values.baseMin > 0);
}
function valuesDiffer(first, second) {
  return ['baseMin', 'baseFee', 'addUnitMin', 'addFee', 'weekdayOpen', 'weekdayClose']
    .some((key) => first[key] !== second[key]);
}

const matches = new Map();
const usedStandard = new Set();
let mismatched = 0;

for (const seoul of context.seoulRows) {
  const normalized = normalizeName(seoul.PKLT_NM);
  if (!normalized) continue;
  const seoulDong = dongs(seoul.ADDR)[0] ?? null;
  let matchedIndex = -1;
  for (let index = 0; index < context.standardLots.length; index += 1) {
    if (usedStandard.has(index)) continue;
    const standard = context.standardLots[index];
    if (standard.areaName !== '대치동') continue;
    if (normalizeName(standard.prkplceNm) !== normalized) continue;
    const standardDongs = dongs([standard.rdnmadr, standard.lnmadr, standard.prkplceNm].join(' '));
    if (seoulDong && standardDongs.some((dong) => dong !== seoulDong)) continue;
    matchedIndex = index;
    break;
  }
  if (matchedIndex < 0) continue;
  usedStandard.add(matchedIndex);
  matches.set(matchedIndex, seoul);
  if (valuesDiffer(standardValues(context.standardLots[matchedIndex]), seoulValues(seoul))) mismatched += 1;
}

const lots = context.standardLots.map((standard, index) => {
  const seoul = matches.get(index) ?? null;
  const standardDate = validDate(standard.referenceDate);
  const seoulDate = seoul ? validDate(seoul.LAST_DATA_SYNC_TM) : null;
  const useSeoul = Boolean(seoul && seoulDate && (!standardDate || seoulDate >= standardDate)
    && seoulUsable(seoul, seoulValues(seoul)));
  const selected = useSeoul ? seoulValues(seoul) : standardValues(standard);
  const dayMaxFee = seoul ? positiveOrNull(seoul.DLY_MAX_CRG) : null;
  return {
    areaId: standard.areaId,
    lotName: text(standard.prkplceNm),
    address: text(standard.rdnmadr) || text(standard.lnmadr) || null,
    lat: Number(standard.latitude),
    lng: Number(standard.longitude),
    weekdayOpen: selected.weekdayOpen,
    weekdayClose: selected.weekdayClose,
    satOpen: selected.satOpen,
    satClose: selected.satClose,
    holidayOpen: selected.holidayOpen,
    holidayClose: selected.holidayClose,
    baseMin: selected.baseMin,
    baseFee: selected.baseFee,
    addUnitMin: selected.addUnitMin,
    addFee: selected.addFee,
    dayPassFee: positiveOrNull(standard.dayCmmtkt),
    dayMaxFee: dayMaxFee && dayMaxFee > 0 ? dayMaxFee : null,
    totalSpaces: nonNegativeOrNull(standard.prkcmprt),
    realtimeRef: null,
    sourceRef: text(standard.prkplceNo),
    feeSource: useSeoul ? 'SEOUL' : 'STANDARD',
    feeBaseDate: useSeoul ? seoulDate : standardDate,
    seoulRef: seoul && text(seoul.PKLT_CD) ? text(seoul.PKLT_CD) : null,
  };
});

return [{
