  const response = item.json;
  const status = Number(response.statusCode);
  const parsed = parseBody(response.body);
  const code = parsed?.resultCode;
  if (status !== 200 || String(code) !== '0') {
    reason ||= failureReason(status, code);
    continue;
  }
  const rawFacilities = asArray(parsed?.PrkSttusInfo);
  rawCount += rawFacilities.length;
  facilities.push(...rawFacilities
    .filter((row) => realtimeSet.has(String(row.prk_center_id ?? '').trim())));
}

