const context = $input.first().json;

function distanceM(firstLat, firstLng, secondLat, secondLng) {
  const meanLat = (firstLat + secondLat) * Math.PI / 360;
  const dy = (secondLat - firstLat) * 110540;
  const dx = (secondLng - firstLng) * 111320 * Math.cos(meanLat);
  return Math.hypot(dx, dy);
}

const facilities = context.facilities
  .map((row) => ({
    id: String(row.prk_center_id ?? '').trim(),
    lat: Number(row.prk_plce_entrc_la),
    lng: Number(row.prk_plce_entrc_lo),
  }))
  .filter((row) => row.id && Number.isFinite(row.lat) && Number.isFinite(row.lng));

let realtimeLinked = 0;
const lots = context.lots.map((lot) => {
  let nearest = null;
  let nearestDistance = Infinity;
  for (const facility of facilities) {
    const distance = distanceM(lot.lat, lot.lng, facility.lat, facility.lng);
    if (distance < nearestDistance) {
      nearest = facility;
      nearestDistance = distance;
    }
  }
  if (nearest && nearestDistance <= 100) {
    realtimeLinked += 1;
    return { ...lot, realtimeRef: nearest.id };
  }
  return lot;
});

return [{ json: { ...context, lots, realtimeLinked } }];

